import sqlite3
import pandas as pd

def task_func(db_name, table_name):
    conn = sqlite3.connect(db_name)
    try:
        safe_table_name = table_name.replace('"', '""')
        df = pd.read_sql_query(f'SELECT * FROM "{safe_table_name}"', conn)
    finally:
        conn.close()

    if "id" in df.columns:
        df = df.drop(columns=["id"])

    numeric_df = df.select_dtypes(include="number")

    if len(numeric_df.columns) < 2:
        raise ValueError("The table has less than two numerical columns.")

    x_col, y_col = numeric_df.columns[:2]

    ax = numeric_df.plot.scatter(x=x_col, y=y_col)
    ax.set_xlabel(x_col)
    ax.set_ylabel(y_col)

    return ax
